"""Fixed real-guest text/archive fixtures, independent of application execution."""
from foundation_guest_fixtures import lesson
UNIT='lpic-text-archive-tools'
DATA=[
lesson('textarchive','streams','Route errors without losing their status',
 'Distinguish standard output, standard error and descriptor-order effects while retaining a failing command’s actual status.',
 'Produce separate data/error records and a combined record from the supplied failing producer. Demonstrate why reversing descriptor order routes error output differently. Retain status7 and explain the difference; do not hide failure.',
 [
 (r'''here && fresh out.txt err.txt status.txt && { bash -c 'printf "data\n"; printf "problem\n" >&2; exit 7' > out.txt 2> err.txt; rc=$?; printf '%s\n' "$rc" > status.txt; test "$rc" = 7; } && cat out.txt err.txt status.txt''','Redirections route bytes; they do not turn failure into success. Save $? before another command replaces it.','data, problem, and status7 in separate files.'),
 (r'''here && fresh combined.txt && { bash -c 'printf "data\n"; printf "problem\n" >&2; exit 7' > combined.txt 2>&1; rc=$?; test "$rc" = 7; } && cat combined.txt''','2>&1 duplicates the stdout descriptor at this moment. Both streams now reach the same file.','Two ordered lines: data then problem.'),
 (r'''here && fresh only-data.txt earlier-stdout.txt && { bash -c 'printf "data\n"; printf "problem\n" >&2; exit 7' 2>&1 > only-data.txt; rc=$?; test "$rc" = 7; } > earlier-stdout.txt && cat only-data.txt earlier-stdout.txt''','When 2>&1 occurs first it still refers to the enclosing group’s stdout, not the subsequently opened file. This is real descriptor ordering, not transactional redirection.','only-data contains data; earlier-stdout contains problem.')],
 ['out.txt','err.txt','status.txt','combined.txt','only-data.txt','earlier-stdout.txt'],
 assertions=[r'''test "$(cat out.txt)" = data && test "$(cat err.txt)" = problem && test "$(cat status.txt)" = 7 && test "$(cat combined.txt)" = "$(printf 'data\nproblem')" && cmp out.txt only-data.txt && cmp err.txt earlier-stdout.txt'''],
 negative=['! cmp -s out.txt err.txt && ! cmp -s combined.txt only-data.txt'],
 hints=['Save the producer’s status immediately.','Follow which descriptor 2 duplicates before descriptor1 changes.'],
 mistakes=['A later cat returning0 does not prove the producer succeeded.','Reversing the two redirections is observably different.'],objectives=['partial103.4 streams/redirection'],
 materials=[r'''Producer: bash -c 'printf "data\n"; printf "problem\n" >&2; exit 7'. It deliberately fails; output filenames are declared above. No repair command is required by the Challenge.''']),
lesson('textarchive','tee','Keep partial output and inspect every pipeline stage',
 'Use tee and immediate PIPESTATUS to distinguish useful partial output from a successful pipeline.',
 'Retain the supplied producer’s partial output in a file and downstream result. Show all stage statuses, then demonstrate pipefail and distinguish grep no-match from an input error.',
 [(r'''here && fresh capture.txt sorted.txt stages.txt && { bash -c 'printf "beta\nalpha\n"; exit 7' | tee capture.txt | LC_ALL=C sort > sorted.txt; ps=("${PIPESTATUS[@]}"); printf '%s\n' "${ps[*]}" > stages.txt; test "${ps[*]}" = '7 0 0'; } && cat stages.txt sorted.txt''','Even an assignment or echo changes PIPESTATUS: snapshot it immediately. The last stage succeeding does not erase upstream failure or partial files.','7 0 0; sorted alpha/beta and retained unsorted producer bytes.'),
 (r'''here && fresh pipefail.txt && { bash -o pipefail -c 'printf "partial\n"; exit 7' | cat > pipefail.txt; ps=("${PIPESTATUS[@]}"); test "${ps[*]}" = '7 0'; }''','The child’s pipefail setting alone does not change the parent pipeline policy. Stage statuses still establish failure.','The file retains partial; upstream7, downstream0.'),
 (r'''here && fresh policy.txt codes.txt && { bash -o pipefail -c 'bash -c '\''printf "partial\n"; exit 7'\'' | tee policy.txt >/dev/null'; rc=$?; grep -F absent capture.txt >/dev/null; nomatch=$?; grep -F absent missing.txt >/dev/null 2>&1; error=$?; printf '%s %s %s\n' "$rc" "$nomatch" "$error" > codes.txt; test "$rc $nomatch $error" = '7 1 2'; } && cat codes.txt''','Enable pipefail in the shell which owns the pipeline. grep status1 means no selected line, not status2 input failure.','7 1 2, with the actual partial file retained.')],
 ['capture.txt','sorted.txt','stages.txt','pipefail.txt','policy.txt','codes.txt'],
 assertions=[r'''test "$(cat stages.txt)" = '7 0 0' && test "$(cat codes.txt)" = '7 1 2' && test "$(cat sorted.txt)" = "$(printf 'alpha\nbeta')" && test "$(cat capture.txt)" = "$(printf 'beta\nalpha')" && cmp pipefail.txt policy.txt'''],
 negative=['! cmp -s capture.txt sorted.txt'],hints=['Which shell owns the pipeline?','Snapshot the whole array before any diagnostic command.'],
 mistakes=['tee is not rollback: partial bytes remain.','Treating grep1 and grep2 as the same error loses evidence.'],objectives=['partial103.4 pipelines/tee','105.2 error-handling reinforcement'],
 materials=[r'''Producer emits beta then alpha and exits7. Required observations: every stage status, byte order before/after sort, parent pipefail result, grep no-match and missing-input statuses.''']),
lesson('textarchive','xargs','Pass awkward filenames without splitting them',
 'Use NUL-delimited bounded xargs, including spaces, backslashes and empty input, without treating names as shell code.',
 'Hash two declared awkward filenames, passing each pathname literally to sha256sum. Bound xargs batches to at most two names, with no parallel execution. Prove empty input starts no command with -r. Contrast a deliberately wrong whitespace parser using only printf, never deletion.',
 [(r'''here && fresh source names.bin hashes.txt empty.bin empty.txt broken.txt && mkdir source && printf 'one\n' > 'source/space name.txt' && printf 'two\n' > 'source/back\slash.txt' && find -P source -type f -print0 > names.bin''','NUL is a pathname separator that cannot appear inside a Unix filename. Quotes in a text list are not reliable filename framing.','Exactly two supplied regular files and two NUL terminators.'),
 (r'''here && dir_ok source && timeout -k 1s 8s xargs -0 -r -n 1 sh -c 'test "$#" = 1 && sha256sum -- "$1"' sh < names.bin > hashes.txt && test "$(tr -cd '\000' < names.bin | wc -c)" = 2 && cat hashes.txt''','-0 preserves literal whitespace/backslashes, -r avoids a no-input invocation, -n1 bounds each argument batch. Never interpolate the name into executable shell text. GNU sha256sum escapes awkward display names.','Two successful hash records; no source changed.'),
 (r'''here && : > empty.bin && timeout -k 1s 8s xargs -0 -r printf 'SHOULD_NOT_RUN\n' < empty.bin > empty.txt && test ! -s empty.txt && printf '%s\n' 'source/space name.txt' | xargs -n 1 printf '<%s>\n' > broken.txt && cat broken.txt''','The wrong parser receives one line but produces two arguments. This controlled contrast only prints: it cannot delete a mistaken target.','No empty-input output; broken list splits source/space and name.txt.')],
 ['source/space name.txt',r'source/back\slash.txt','names.bin','hashes.txt','empty.bin','empty.txt','broken.txt'],['source'],
 assertions=[r'''sha256sum -c hashes.txt && test "$(cat broken.txt)" = "$(printf '<source/space>\n<name.txt>')" && test ! -s empty.txt'''],
 negative=[r'''test "$(cat broken.txt)" != '<source/space name.txt>' '''],
 hints=['Choose a delimiter, not backslash escaping.','Use -- before filenames where the receiving command supports it.'],
 mistakes=['Plain xargs is not safe filename handling.','Without GNU -r an empty input may still invoke the command once.'],objectives=['partial103.3 safe names/xargs','partial103.4 command composition'],
 materials=[r'''Create only source/space name.txt containing one newline-terminated line "one", and source/back\slash.txt containing "two". Preserve both. Use harmless printf for the wrong-parser comparison.''']),
lesson('textarchive','join','Reconcile sorted records without hiding missing keys',
 'Join two small key tables and use comm to retain unmatched evidence, with a consistent locale and checked ordering.',
 'Reconcile the supplied independent tables, retaining unmatched keys explicitly. Produce left-only/right-only key lists. Demonstrate unsorted-input rejection and explain duplicate-key ambiguity.',
 [(r'''here && fresh left.txt right.txt joined.txt left.keys right.keys left-only.txt right-only.txt unsorted.txt rejected.txt && printf 'alpha 2\nbeta 5\n' > left.txt && printf 'alpha healthy\ngamma stale\n' > right.txt && printf 'zeta 9\nalpha 2\n' > unsorted.txt''','These are whitespace-separated keys without embedded blanks, not CSV. alpha matches; beta and gamma represent missing evidence, not zero values.','Two independent tables and a separate deliberately unsorted input.'),
 (r'''here && LC_ALL=C join --check-order -a 1 -a 2 -e UNKNOWN -o 0,1.2,2.2 left.txt right.txt > joined.txt && cut -d ' ' -f1 left.txt > left.keys && cut -d ' ' -f1 right.txt > right.keys && LC_ALL=C comm --check-order -23 left.keys right.keys > left-only.txt && LC_ALL=C comm --check-order -13 left.keys right.keys > right-only.txt && cat joined.txt left-only.txt right-only.txt''','Both producers and consumers must agree on sort order. Outer join preserves unmatched keys; UNKNOWN prevents false numeric conclusions. comm compares already sorted complete lines.','alpha 2 healthy; beta 5 UNKNOWN; gamma UNKNOWN stale; beta left-only and gamma right-only.'),
 (r'''here && { LC_ALL=C join --check-order unsorted.txt right.txt > rejected.txt 2>/dev/null; rc=$?; test "$rc" != 0; }''','Rejected input can leave partial output. Retain it as failed evidence, not a valid reconciliation. Duplicate keys can yield multiple matched pairs, not a unique entity record.','Nonzero status for unsorted input; source tables unchanged.')],
 ['left.txt','right.txt','joined.txt','left.keys','right.keys','left-only.txt','right-only.txt','unsorted.txt','rejected.txt'],
 assertions=[r'''test "$(cat joined.txt)" = "$(printf 'alpha 2 healthy\nbeta 5 UNKNOWN\ngamma UNKNOWN stale')" && test "$(cat left-only.txt)" = beta && test "$(cat right-only.txt)" = gamma && test "$(cat left.txt)" = "$(printf 'alpha 2\nbeta 5')" '''],negative=['! cmp -s left.keys right.keys'],
 hints=['Which keys would an inner join silently omit?','LC_ALL=C must apply consistently, not just to the final consumer.'],mistakes=['Unmatched is not equivalent to zero.','Duplicate keys need a policy; join does not invent uniqueness.'],objectives=['partial103.2 join/comm/filter composition'],
 materials=['Tables: left = alpha 2; beta 5. Right = alpha healthy; gamma stale. Bad-order table = zeta 9; alpha 2. Retain all three.']),
lesson('textarchive','find','Group a bounded search and batch safe inspections',
 'Combine find pruning and grouped alternatives, then batch read-only inspection of the resulting regular files.',
 'Within the supplied tree, inspect current .txt or .log regular files, pruning the old directory. Retain source checksums and show the mistaken precedence case. Never delete through find.',
 [(r'''here && fresh tree selected.txt wrong.txt original.sha && mkdir tree tree/old tree/dir.log && printf 'new\n' > tree/'space name.txt' && printf 'event\n' > tree/current.log && printf 'old\n' > tree/old/stale.txt && sha256sum tree/'space name.txt' tree/current.log tree/old/stale.txt > original.sha''','All targets are a tiny declared tree. dir.log is deliberately a directory, so a suffix alone is insufficient.','Three original files and one misleading directory name.'),
 (r'''here && dir_ok tree && dir_ok tree/old && timeout -k 1s 8s find -P tree -path tree/old -prune -o -type f \( -name '*.txt' -o -name '*.log' \) -exec sh -c 'for f; do printf "%s " "$f"; wc -c < "$f"; done' sh {} + > selected.txt && cat selected.txt''','-prune belongs before the alternative; grouped suffixes both require -type f. {} + batches pathname arguments without turning them into shell source. This inspection is read-only.','Only space name.txt(4 bytes) and current.log(6 bytes); old subtree and dir.log excluded.'),
 (r'''here && dir_ok tree && dir_ok tree/old && timeout -k 1s 8s find -P tree -type f -name '*.txt' -o -name '*.log' > wrong.txt && grep -qx tree/dir.log wrong.txt && sha256sum -c original.sha''','Without grouping, the .log alternative does not inherit -type f. This wrong query prints only; it does not mutate targets.','Wrong query includes dir.log, while every original checksum still matches.')],
 ['tree/space name.txt','tree/current.log','tree/old/stale.txt','selected.txt','wrong.txt','original.sha'],['tree/old','tree/dir.log','tree'],
 assertions=[r'''LC_ALL=C sort selected.txt | cmp - <(printf 'tree/current.log 6\ntree/space name.txt 4\n') && ! grep -q stale selected.txt && sha256sum -c original.sha'''],
 negative=['grep -qx tree/dir.log wrong.txt && ! grep -q dir.log selected.txt'],
 hints=['Parentheses change predicate precedence.','Use -P and restrict the root; do not add destructive actions.'],mistakes=['Suffix matching can include directories.','find does not make shell interpolation safe.'],objectives=['partial103.3 find combinations','partial103.4 batched command composition'],
 materials=['Create tree/space name.txt = new newline; tree/current.log = event newline; tree/old/stale.txt = old newline; empty tree/dir.log. The old subtree must be pruned.']),
lesson('textarchive','cpio','Restore a trusted relative newc archive separately',
 'Create, inspect and restore a small newc cpio archive of known regular files without replacing originals.',
 'Archive the two supplied regular files with literal NUL names. Verify exact members and retained hash, restore to a new empty destination, then compare contents and modes. Explain why this does not admit arbitrary archives safely.',
 [(r'''here && fresh source members.bin expected.txt original.sha copy.cpio archive.sha listed.txt restore && mkdir source && printf 'note\n' > source/note.txt && printf 'spaced\n' > source/'space name.txt' && chmod 0600 source/note.txt source/'space name.txt' && printf '%s\0' note.txt 'space name.txt' > members.bin && printf '%s\n' note.txt 'space name.txt' > expected.txt && sha256sum source/note.txt source/'space name.txt' > original.sha''','Only these two relative regular files are trusted inputs; no links, devices, absolute paths or parent members. This is practice, not a hostile-archive importer.','Separate small source/reference/member files.'),
 (r'''here && dir_ok source && test -f source/note.txt && test ! -L source/note.txt && test -f source/'space name.txt' && test ! -L source/'space name.txt' && ( cd "$w/source" && test "$(pwd -P)" = "$w/source" && timeout -k 1s 8s cpio -0 -o -H newc --quiet < ../members.bin > ../copy.cpio ) && test "$(stat -c %s copy.cpio)" -le 65536 && sha256sum copy.cpio > archive.sha''','newc is explicitly selected. NUL input preserves the space name. The timeout and measured size bound this trusted fixture, not arbitrary input.','A private bounded archive; original hashes retained separately.'),
 (r'''here && dir_ok source && sha256sum -c archive.sha && timeout -k 1s 8s cpio -it --quiet < copy.cpio > listed.txt && cmp expected.txt listed.txt && fresh restore && mkdir restore && dir_ok restore && ( cd "$w/restore" && test "$(pwd -P)" = "$w/restore" && timeout -k 1s 8s cpio -id --no-absolute-filenames --quiet < ../copy.cpio ) && cmp source/note.txt restore/note.txt && cmp source/'space name.txt' restore/'space name.txt' && test "$(stat -c %a restore/note.txt)" = 600 && test "$(stat -c %a restore/'space name.txt')" = 600 && sha256sum -c original.sha''','Inspect before extraction, and use a fresh empty separate target. --no-absolute-filenames alone is not a general archive safety guarantee. Hashes detect change against a trusted retained reference; they do not establish authenticity.','Exact members, contents and mode; original source unchanged.')],
 ['source/note.txt','source/space name.txt','members.bin','expected.txt','original.sha','copy.cpio','archive.sha','listed.txt','restore/note.txt','restore/space name.txt'],['source','restore'],
 assertions=[r'''cmp expected.txt listed.txt && sha256sum -c archive.sha original.sha && cmp source/note.txt restore/note.txt && cmp source/'space name.txt' restore/'space name.txt' '''],
 negative=[r'''printf 'unexpected\n' | cmp -s expected.txt; rc=$?; test "$rc" != 0'''],
 hints=['A listing is not a contents comparison.','Use exact known relative names and a fresh destination.'],mistakes=['--no-absolute-filenames does not reject every dangerous link or parent-path archive.','A correct cpio exit status alone does not prove intended bytes.'],objectives=['partial103.3 cpio archive management'],
 materials=['Two known regular files: note.txt=note newline; space name.txt=spaced newline; both0600. Preserve their independent hashes and archive hash. No arbitrary imported archives.']),
lesson('textarchive','composition','Reject a valid compressed partial backup',
 'Diagnose tar-to-gzip pipeline failure, retaining the real partial candidate and creating a separate verified retry.',
 'Demonstrate a failed archive producer followed by successful compression. Prove the first gzip stream is valid but incomplete; retain it, then build and restore a different complete candidate without changing sources.',
 [(r'''here && fresh source original.sha partial.tar.gz stages.txt complete.tar.gz complete.sha members.txt restore && mkdir source && printf 'alpha\n' > source/alpha.txt && printf 'beta\n' > source/beta.txt && sha256sum source/alpha.txt source/beta.txt > original.sha''','A missing requested member will cause the producer to fail, but downstream gzip can still write a valid stream. Keep originals and the failed candidate.','Two originals; no output reused.'),
 (r'''here && dir_ok source && { timeout -k 1s 8s tar -cf - -C source -- alpha.txt absent.txt 2>/dev/null | timeout -k 1s 8s gzip -n > partial.tar.gz; ps=("${PIPESTATUS[@]}"); printf '%s\n' "${ps[*]}" > stages.txt; test "${ps[0]}" != 0 && test "${ps[1]}" = 0; } && gzip -t partial.tar.gz && tar -tzf partial.tar.gz''','Redirection and compression are not transactional. gzip CRC validates that stream, not completeness or expected source data. Save every stage status immediately.','Partial archive exists and gzip testing passes, despite a failing tar stage.'),
 (r'''here && dir_ok source && { timeout -k 1s 8s tar -cf - -C source -- alpha.txt beta.txt | timeout -k 1s 8s gzip -n > complete.tar.gz; ps=("${PIPESTATUS[@]}"); test "${ps[*]}" = '0 0'; } && test "$(stat -c %s complete.tar.gz)" -le 65536 && sha256sum complete.tar.gz > complete.sha && tar -tzf complete.tar.gz > members.txt && cmp members.txt <(printf 'alpha.txt\nbeta.txt\n') && fresh restore && mkdir restore && dir_ok restore && timeout -k 1s 8s tar -xzf complete.tar.gz -C restore --no-same-owner --same-permissions && cmp source/alpha.txt restore/alpha.txt && cmp source/beta.txt restore/beta.txt && sha256sum -c original.sha complete.sha''','The retry gets a new filename and destination. Compare declared members and independent content expectations; never accept an earlier failed output merely because it decompresses.','Both complete restored files match, failed candidate remains and originals are unchanged.')],
 ['source/alpha.txt','source/beta.txt','original.sha','partial.tar.gz','stages.txt','complete.tar.gz','complete.sha','members.txt','restore/alpha.txt','restore/beta.txt'],['source','restore'],
 assertions=[r'''test "$(tar -tzf partial.tar.gz)" = alpha.txt && test "$(tar -tzf complete.tar.gz)" = "$(printf 'alpha.txt\nbeta.txt')" && sha256sum -c original.sha complete.sha'''],
 negative=['! cmp -s partial.tar.gz complete.tar.gz'],
 hints=['Inspect the producer status, not just gzip -t.','A retry should preserve the failed candidate and use a fresh destination.'],mistakes=['pipefail reports failure but does not remove partial output.','An empty/missing-member archive may still be syntactically valid.'],objectives=['partial103.4 pipelines/error evidence','103.3/105.2/206.2 reinforcement'],
 materials=['Originals alpha.txt=alpha newline and beta.txt=beta newline. Deliberately request absent.txt only in the failed candidate. Use two different backup names and retain both.']),
lesson('textarchive','handover','Recover text evidence and hand over uncertainty',
 'Independently restore the right report version and reconcile factual records while preserving a wrong-but-valid backup.',
 'Two known compressed reports are both valid; only one matches the independently retained expected hash. Restore it separately, select the confirmed ERROR records, retain timestamp/context and explain what the report cannot prove. Preserve both candidates and all originals.',
 [(r'''here && fresh current.txt expected.sha old.txt old.gz accepted.gz accepted.sha restore.txt evidence.txt && printf '2026-10-11T12:00Z host-a INFO ready\n2026-10-11T12:01Z host-a ERROR input-missing\n' > current.txt && printf '2026-10-10T12:00Z host-a INFO ready\n' > old.txt && sha256sum current.txt > expected.sha && gzip -n -c old.txt > old.gz && gzip -n -c current.txt > accepted.gz && sha256sum accepted.gz > accepted.sha''','These are original fictional guest-local records, not live system diagnosis. The expected hash is retained independently of the two compressed candidates.','A current report, older valid report, two distinct compressed candidates and references.'),
 (r'''here && gzip -t old.gz accepted.gz && { gzip -dc old.gz | cmp -s - current.txt; ps=("${PIPESTATUS[@]}"); test "${ps[0]}" = 0 && test "${ps[1]}" = 1; }''','Both streams pass compression checks, but the older payload fails expected contents. Do not overwrite a reference to make the wrong candidate appear correct.','Wrong selection is demonstrably rejected without altering either candidate.'),
 (r'''here && sha256sum -c accepted.sha expected.sha && gzip -dc accepted.gz > restore.txt && cmp current.txt restore.txt && grep -E '^[0-9T:Z-]+ host-a ERROR ' restore.txt > evidence.txt && cat evidence.txt''','Choose an equivalent supported filter and verify the exact retained timestamp/host/event. Your interpretation of cause, urgency and next checks is self-reviewed, not keyword-scored.','Only the 12:01 input-missing event, with original context and copies preserved.')],
 ['current.txt','expected.sha','old.txt','old.gz','accepted.gz','accepted.sha','restore.txt','evidence.txt'],
 assertions=[r'''test "$(cat evidence.txt)" = '2026-10-11T12:01Z host-a ERROR input-missing' && cmp current.txt restore.txt && sha256sum -c accepted.sha expected.sha'''],
 negative=['! cmp -s current.txt old.txt'],
 hints=['Format validity does not select the correct recovery point.','Separate reported error evidence from a causal conclusion.'],mistakes=['A recent filename is not proof of the right payload.','The error line does not prove why the input was missing.'],objectives=['103.2/103.3/103.4/105.2 reinforcement; independent transfer'],
 materials=[r'''Initial fixture, not repair: here && fresh current.txt expected.sha old.txt old.gz accepted.gz accepted.sha restore.txt evidence.txt && printf '2026-10-11T12:00Z host-a INFO ready\n2026-10-11T12:01Z host-a ERROR input-missing\n' > current.txt && printf '2026-10-10T12:00Z host-a INFO ready\n' > old.txt && sha256sum current.txt > expected.sha && gzip -n -c old.txt > old.gz && gzip -n -c current.txt > accepted.gz && sha256sum accepted.gz > accepted.sha''', 'In Challenge select by expected bytes/hash, not filename alone. Report fields: timestamp, host, observed event, rejected candidate, uncertainty and next check.'])
]
COMMANDS={x['id']:x['commands'] for x in DATA}

for x in DATA:
 x['challenge_commands']=list(x['commands'])
 if x['slug'] in ('streams','join','find'):x['challenge_commands'][2:4]=reversed(x['challenge_commands'][2:4])
 if x['slug']=='xargs':x['challenge_commands'][2]=x['commands'][2].replace("-n 1 sh -c 'test \"$#\" = 1 && sha256sum -- \"$1\"' sh","-n 2 sh -c 'for f; do sha256sum -- \"$f\" || exit; done' sh")
 if x['slug']=='handover':x['challenge_commands'][3]=x['commands'][3].replace("grep -E '^[0-9T:Z-]+ host-a ERROR '","awk '$2 == \"host-a\" && $3 == \"ERROR\"'")

# Certification namespaces remain explicit; 206.2 belongs to LPIC-2.
for x in DATA:
 if x["slug"] == "composition":
  x["content"]["coverage"] = "LPIC-1 v5.0: partial 103.4 pipeline/error evidence; 103.3/105.2 reinforcement. LPIC-2 v4.5.0: related 206.2 recovery reinforcement only. Self-reviewed and unscored; no full coverage."
